stepxmp.pre:
table {
    display: table;
    border-spacing: 4pt 2pt;
}

cell {
    display: table-cell;
    border: 1pt solid gray;
}

table {
    display: table;
    border-collapse: collapse;
    border: 2pt solid black;
}

cell {
    display: table-cell;
    border: 0.5pt solid gray;
}

header {
    display: table-header-group;
    background-color: #e0e0e0;
    font-weight: bold;
}

row:nth-child(even) {
    background-color: #f5f5f5;
}
